page_settings.custom_css:
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:ital,wght@0,300..800;1,300..800&display=swap');
:root{
  --o:#F86838; --o-dk:#E5542A; --o-tint:#FFF0EA; --yellow:#F8C848; --blue:#3088F8;
  --ink:#0F0F0F; --body:#555; --muted:#8A8A8A; --bg:#FFF; --bg-alt:#F7F7F5; --line:#ECECEC; 
}
body,.elementor-widget-heading .elementor-heading-title,.elementor-widget-text-editor,
.elementor-button{font-family:'Plus Jakarta Sans',system-ui,sans-serif !important;}

/* Headings */
.h-xl .elementor-heading-title{font-size:clamp(38px,5vw,62px);font-weight:800;line-height:1.05;letter-spacing:-0.025em;color:var(--ink);}
.h-lg .elementor-heading-title{font-size:clamp(30px,3.6vw,46px);font-weight:800;line-height:1.1;letter-spacing:-0.02em;color:var(--ink);}
.h-md .elementor-heading-title{font-size:clamp(22px,2.4vw,30px);font-weight:800;line-height:1.15;letter-spacing:-0.015em;color:var(--ink);}
.accent .elementor-heading-title,.accentword{color:var(--o);}
    .accentwordb{color:var(--blue);}
    .accentwordy{color:var(--yellow);}

.italic .elementor-heading-title{font-style:italic;}
.center .elementor-heading-title,.center .elementor-widget-container{text-align:center;}
.lead .elementor-widget-container{font-size:17px;line-height:1.6;color:var(--body);}
.lead.center .elementor-widget-container{max-width:640px;margin:0 auto;}

/* Eyebrow */
.eyebrow-wrap .eyebrow{display:inline-block;font-size:12px;font-weight:700;letter-spacing:0.14em;text-transform:uppercase;color:var(--o);}

/* Buttons spacing in a flex row */
.btnrow{display:flex;gap:14px;flex-wrap:wrap;}

/* Feature list (pricing) */
.feat .elementor-widget-container ul{list-style:none;margin:0;padding:0;}
.feat .elementor-widget-container li{position:relative;padding:7px 0 7px 28px;font-size:14px;color:var(--body);border-bottom:1px solid var(--line);}
.feat .elementor-widget-container li::before{content:'';position:absolute;left:0;top:11px;width:16px;height:16px;border-radius:50%;background:var(--o-tint);}
.feat .elementor-widget-container li::after{content:'';position:absolute;left:5px;top:15px;width:6px;height:3px;border-left:2px solid var(--o);border-bottom:2px solid var(--o);transform:rotate(-45deg);}
.feat.on-orange .elementor-widget-container li{color:#fff;border-color:rgba(255,255,255,0.25);}
.feat.on-orange .elementor-widget-container li::before{background:rgba(255,255,255,0.25);}
.feat.on-orange .elementor-widget-container li::after{border-color:#fff;}
.feat .elementor-widget-container li strong{color:inherit;font-weight:700;}

/* Pricing card */
.pcard{background:#fff;border:1px solid var(--line);border-radius:18px;padding:30px 26px;height:100%;}
.pcard.featured{background:var(--o);border-color:var(--o);}
.pcard.featured .elementor-heading-title,.pcard.featured .elementor-widget-text-editor{color:#fff !important;}
.price-amt .elementor-heading-title{font-size:40px;font-weight:800;letter-spacing:-0.03em;}
.price-amt sup{font-size:20px;font-weight:700;vertical-align:super;}

/* Story / testimonial card */
.qcard{background:#fff;border:1px solid var(--line);border-radius:16px;padding:22px;height:100%;}
.qcard .q{font-size:14px;line-height:1.6;color:var(--body);font-style:italic;}
.qcard .who{font-size:13px;font-weight:700;color:var(--ink);margin-top:12px;}
.qcard .role{font-size:12px;color:var(--muted);}

/* Stat */
.stat-num .elementor-heading-title{font-size:64px;font-weight:800;letter-spacing:-0.04em;color:var(--ink);line-height:1;}
.stat-num.o .elementor-heading-title{color:var(--o);}
.stat-cap .elementor-widget-container{font-size:13px;font-weight:600;letter-spacing:0.1em;text-transform:uppercase;color:var(--muted);text-align:center;}

/* Process number */
.pnum .elementor-heading-title{font-size:54px;font-weight:800;color:var(--o-tint);line-height:1;}

/* Orange band */
.oband{background:var(--o);border-radius:22px;}
.oband .elementor-heading-title{color:#fff;}

/* Section number badge */
.numbadge{width:34px;height:34px;border-radius:50%;background:var(--o);color:#fff;display:flex;align-items:center;justify-content:center;font-weight:800;}

/* Circle-underline accent on a word (results / Easy) */
.squiggle{position:relative;display:inline-block;color:var(--o);}
.squiggle::after{content:'';position:absolute;left:0;right:0;bottom:-6px;height:8px;background:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 10'><path d='M2 6 Q 25 0 50 5 T 98 4' stroke='%23F86838' stroke-width='3' fill='none' stroke-linecap='round'/></svg>") no-repeat;background-size:100% 100%;}

/* Tickers */
.ticker{overflow:hidden;white-space:nowrap;padding:18px 0;font-weight:800;font-size:clamp(22px,3vw,34px);letter-spacing:-0.01em;}
.ticker.blue{background:var(--blue);color:#fff;transform:rotate(-2deg);}
.ticker.yellow{background:var(--yellow);color:var(--ink);transform:rotate(2deg);}
.ticker span{display:inline-block;padding:0 26px;}

/* Logo grid */
.logogrid img{filter:grayscale(1);opacity:0.7;}
